insert into public.sections (id, stage_id, title, body, sort_order) values ($qa$ib-m2-s6$qa$, $qa$ib-m2$qa$, $qa$Jenis Agent$qa$, $qa$<p>Jenis Agent 1. Simple reflex agents: berdasarkan persepsi yg terakhir Inteligensi Buatan 2026 28</p>
<p>Jenis Agent 2. Model-based reflex agents: memiliki representasi internal tentang keadaan sekitar Inteligensi Buatan 2026 29</p>
